"""Content specs for ACT 144-148 (exact texts verified against parsed JSON)."""
import json, os
JDIR = "/home/user/tools/articles"
_cache = {}
def A(act, key):
    if act not in _cache:
        _cache[act] = json.load(open(os.path.join(JDIR, f"{act}.json")))
    for s in _cache[act]["segments"]:
        if s["kind"] == "article" and s["key"] == key:
            return s["text"]
    raise KeyError(f"article {act}.{key} not found")
def P(act, kind):
    """Fetch non-article segment (preamble etc.) by kind (first match)."""
    d = _cache.get(act)
    if d is None:
        d = _cache[act] = json.load(open(os.path.join(JDIR, f"{act}.json")))
    for s in d["segments"]:
        if s["kind"] == kind:
            return s["text"]
    raise KeyError(f"{act} {kind} not found")
def mark(text, *specs):
    """specs: plain string = mark exact substring; 'LINE:<anchor>' = mark the whole line containing anchor."""
    out = text
    for spec in specs:
        if spec.startswith("LINE:"):
            anchor = spec[5:]
            assert out.count(anchor) == 1, f"LINE anchor not unique/found: {anchor[:60]!r} ({out.count(anchor)})"
            i = out.find(anchor)
            ls = out.rfind("\n", 0, i) + 1
            le = out.find("\n", i)
            if le == -1:
                le = len(out)
            seg = out[ls:le]
            assert "{{" not in seg and "[[" not in seg
            out = out[:ls] + "{{" + seg + "}}" + out[le:]
        else:
            assert out.count(spec) == 1, f"fragment not unique/found ({out.count(spec)}): {spec[:60]!r}"
            out = out.replace(spec, "{{" + spec + "}}")
    return out
